import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 변환 대상 확장자는 HWP·Word·Excel·PPT 계열이다 (결정 AC-7).
const SUPPORTED_EXTENSIONS = ['hwp', 'hwpx', 'doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx'];

function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

@Controller('api/v1')
export class FnSfr03002Controller {
  @Post('/approval-forms/convert')
  @HttpCode(200)
  async convertApprovalForm(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const data = checks.inputOf(req.body);
    const sourceFile = data['sourceFile'];
    if (typeof sourceFile !== 'string' || sourceFile.trim() === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '변환할 파일을 입력해 주세요.');
    }
    const fileName = sourceFile.trim();
    const dot = fileName.lastIndexOf('.');
    const extension = dot >= 0 ? fileName.substring(dot + 1).toLowerCase() : '';
    if (!SUPPORTED_EXTENSIONS.includes(extension)) {
      throw new ApiError(422, 'UNSUPPORTED_FILE_TYPE', '지원하지 않는 파일 형식입니다. HWP·Word·Excel·PPT 파일만 변환할 수 있습니다.');
    }
    const baseName = dot > 0 ? fileName.substring(0, dot) : '';
    if (baseName.trim() === '') {
      throw new ApiError(422, 'FORM_CONVERT_FAILED', '파일을 HTML 양식으로 변환하지 못했습니다.');
    }
    // 가정: 변환 엔진 사양이 없어 파일 이름을 담은 HTML 양식 뼈대를 만든다. 편집은 웹 기안기에서 이어서 한다.
    const bodyContent =
      '<div class="approval-form">\n' +
      '  <h1>' + escapeHtml(baseName) + '</h1>\n' +
      '  <div class="approval-form-body"></div>\n' +
      '</div>';
    return {
      bodyContent,
      convertSucceeded: true,
      failureReason: '',
    };
  }
}

