import { useState } from 'react';
import { call, Badge, Band, DataTable, Drawer, Field, Form, Select, TextInput, Tiles } from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr03002Page({ role, notify }: PageProps) {
  const [rows, setRows] = useState<Row[]>([]);
  const [mode, setMode] = useState<'' | 'convert' | 'edit'>('');
  const [sourceFile, setSourceFile] = useState('');
  const [editingId, setEditingId] = useState<number | null>(null);
  const [formName, setFormName] = useState('');
  const [bodyContent, setBodyContent] = useState('');
  const [defaultApprovalRule, setDefaultApprovalRule] = useState('');
  const [useStatus, setUseStatus] = useState('사용');

  function close() {
    setMode('');
    setEditingId(null);
  }

  function openConvert() {
    setSourceFile('');
    setMode('convert');
  }

  function openEdit(row: Row) {
    setEditingId(row['approvalFormId'] as number);
    setFormName(String(row['formName'] ?? ''));
    setBodyContent(String(row['bodyContent'] ?? ''));
    setDefaultApprovalRule(String(row['defaultApprovalRule'] ?? ''));
    setUseStatus(String(row['useStatus'] ?? '사용'));
    setMode('edit');
  }

  async function convert() {
    if (sourceFile.trim() === '') {
      throw new Error('변환할 파일을 입력해 주세요.');
    }
    const result = await call<Row>('POST', '/approval-forms/convert', role, { sourceFile: sourceFile.trim() });
    setEditingId(null);
    setFormName('');
    setBodyContent(String(result['bodyContent'] ?? ''));
    setDefaultApprovalRule('');
    setUseStatus('사용');
    notify('파일을 HTML 양식으로 변환했습니다.');
    setMode('edit');
  }

  async function save() {
    if (formName.trim() === '') {
      throw new Error('결재양식명을 입력해 주세요.');
    }
    const body: Row = {
      formName: formName.trim(),
      bodyContent,
      defaultApprovalRule,
      useStatus,
    };
    if (editingId === null) {
      const saved = await call<Row>('POST', '/approval-forms', role, body);
      setRows([{ ...saved, ...body }, ...rows]);
      notify('결재양식을 등록했습니다.');
    } else {
      const saved = await call<Row>('PATCH', '/approval-forms/' + editingId, role, body);
      setRows(rows.map((r) => (r['approvalFormId'] === editingId ? { ...r, ...saved, ...body } : r)));
      notify('결재양식을 수정했습니다.');
    }
    close();
  }

  const usedCount = rows.filter((r) => r['useStatus'] === '사용').length;

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>양식 처리 현황</h2>
        <Tiles
          items={[
            ['저장한 양식', rows.length],
            ['사용 양식', usedCount],
            ['미사용 양식', rows.length - usedCount],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>변환한 양식</h2>
        <Band total={rows.length}>
          <button type="button" onClick={openConvert}>문서 파일 변환</button>
        </Band>
        <DataTable
          rows={rows}
          empty="이 화면에서 저장한 양식이 없습니다."
          columns={[
            { key: 'approvalFormId', label: '결재양식 ID' },
            { key: 'formName', label: '결재양식명' },
            { key: 'useStatus', label: '사용 여부', render: (r) => <Badge value={r['useStatus']} /> },
            {
              key: 'edit',
              label: '처리',
              render: (r) => (
                <button type="button" onClick={() => openEdit(r)}>수정</button>
              ),
            },
          ]}
        />
      </section>
      {mode === 'convert' && (
        <Drawer title="문서 파일 변환" onClose={close}>
          <Form onSubmit={convert} submit="변환">
            <Field label="변환할 HWP·Word·Excel·PPT 파일" required wide hint="예: 휴가신청서.docx">
              <TextInput value={sourceFile} onChange={setSourceFile} placeholder="파일 이름" />
            </Field>
          </Form>
        </Drawer>
      )}
      {mode === 'edit' && (
        <Drawer title={editingId === null ? '변환된 양식 편집·저장' : '결재양식 수정'} onClose={close}>
          <Form onSubmit={save} submit="저장">
            <Field label="결재양식명" required wide>
              <TextInput value={formName} onChange={setFormName} />
            </Field>
            <Field label="사용 여부" required>
              <Select
                value={useStatus}
                onChange={setUseStatus}
                options={[['사용', '사용'], ['미사용', '미사용']]}
              />
            </Field>
            <Field label="기본 결재 규칙" wide>
              <TextInput value={defaultApprovalRule} onChange={setDefaultApprovalRule} multiline />
            </Field>
            <Field label="양식 본문 구성" wide>
              <TextInput value={bodyContent} onChange={setBodyContent} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
